public class TopWordsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<String> words = java.util.List.of("pear", "fig", "banana", "kiwi", "apple", "plum");
        check("top 2 longest", "[banana, apple]", TopWords.longestN(words, 2).toString());
        check("length ties broken alphabetically", "[banana, apple, kiwi, pear]",
                TopWords.longestN(words, 4).toString());
        check("n larger than the list returns everything ordered",
                "[banana, apple, kiwi, pear, plum, fig]",
                TopWords.longestN(words, 10).toString());
        check("n = 0 gives empty list", "[]", TopWords.longestN(words, 0).toString());
        check("all words same length sort alphabetically", "[ant, bee, cow]",
                TopWords.longestN(java.util.List.of("cow", "ant", "bee"), 3).toString());
        check("empty input", "[]", TopWords.longestN(new java.util.ArrayList<String>(), 3).toString());
        check("input list is not modified", "[pear, fig, banana, kiwi, apple, plum]", words.toString());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

